export function upsertSource(
  db: DatabaseSync,
  source: {
    slug: string;
    title: string;
    kind: SourceRow["kind"];
    url: string;
    interest: string;
    weight?: number;
  },
): void {
  db.prepare(
    `INSERT INTO cur_sources (slug, title, kind, url, interest, weight)
     VALUES (?, ?, ?, ?, ?, ?)
     ON CONFLICT(slug) DO UPDATE SET
       title = excluded.title,
       kind = excluded.kind,
       url = excluded.url,
       interest = excluded.interest,
       weight = excluded.weight`,
  ).run(
    source.slug,
    source.title,
    source.kind,
    source.url,
    source.interest,
    source.weight ?? 1,
  );
}

