  return db
    .prepare(
      `SELECT id, slug, title, kind, url, interest, weight, last_fetched_at, fail_count
       FROM cur_sources
       WHERE enabled = 1 AND kind IN ('rss','atom')
       ORDER BY COALESCE(last_fetched_at, '') ASC`,
    )
    .all() as SourceRow[];
}

export function markSourceFetched(
  db: DatabaseSync,
  sourceId: number,
