): TakeRow[] {
  return db
    .prepare(
      `SELECT t.*, i.title AS title, i.url AS url, s.slug AS source_slug
       FROM cur_takes t
       JOIN cur_items i ON i.id = t.item_id
       JOIN cur_sources s ON s.id = i.source_id
