    }
    const initCols = db
      .prepare(`PRAGMA table_info(mem_initiative_log)`)
      .all() as Array<{ name: string }>;
    if (!initCols.some((c) => c.name === "external_message_id")) {
      db.exec(
        `ALTER TABLE mem_initiative_log ADD COLUMN external_message_id TEXT`,
      );
