        `UPDATE mem_initiative_log
         SET external_message_id = discord_message_id
         WHERE external_message_id IS NULL
           AND discord_message_id IS NOT NULL`,
      );
    }
    db.exec(`
CREATE TABLE IF NOT EXISTS mem_reminders (
